#define SPI1_MEM_C_FCS_CRC_EN_M  (SPI1_MEM_C_FCS_CRC_EN_V << SPI1_MEM_C_FCS_CRC_EN_S)
#define SPI1_MEM_C_FCS_CRC_EN_V  0x00000001U
#define SPI1_MEM_C_FCS_CRC_EN_S  10
