#define SPI1_MEM_C_RESANDRES_M  (SPI1_MEM_C_RESANDRES_V << SPI1_MEM_C_RESANDRES_S)
#define SPI1_MEM_C_RESANDRES_V  0x00000001U
#define SPI1_MEM_C_RESANDRES_S  15
