#define SPI1_MEM_C_WRSR_2B_M  (SPI1_MEM_C_WRSR_2B_V << SPI1_MEM_C_WRSR_2B_S)
#define SPI1_MEM_C_WRSR_2B_V  0x00000001U
#define SPI1_MEM_C_WRSR_2B_S  22
