            uint32_t en_aux_snap2 : 1;                /* Auxiliary Snapshot 2 Enable */
            uint32_t en_aux_snap3 : 1;                /* Auxiliary Snapshot 3 Enable */
            uint32_t reserved3 : 3;                   /* Reserved */
