#define H264_A_CHROMA_DC_QP_DELTA    0x00000007U
#define H264_A_CHROMA_DC_QP_DELTA_M  (H264_A_CHROMA_DC_QP_DELTA_V << H264_A_CHROMA_DC_QP_DELTA_S)
#define H264_A_CHROMA_DC_QP_DELTA_V  0x00000007U
