#define ISP_COLOR_HUE_H    (BIT(0))
#define ISP_COLOR_HUE_H_M  (ISP_COLOR_HUE_H_V << ISP_COLOR_HUE_H_S)
#define ISP_COLOR_HUE_H_V  0x00000001U
#define ISP_COLOR_HUE_H_S  0

/** ISP_AWB_BX_REG register
 *  awb window register in x-direction
 */
#define ISP_AWB_BX_REG (DR_REG_ISP_BASE + 0x264)
/** ISP_AWB_X_BSIZE : R/W; bitpos: [11:0]; default: 0;
 *  Configures every block x size, min number is 4
 */
#define ISP_AWB_X_BSIZE    0x00000FFFU
#define ISP_AWB_X_BSIZE_M  (ISP_AWB_X_BSIZE_V << ISP_AWB_X_BSIZE_S)
#define ISP_AWB_X_BSIZE_V  0x00000FFFU
#define ISP_AWB_X_BSIZE_S  0
/** ISP_AWB_X_START : R/W; bitpos: [23:12]; default: 0;
 *  Configures first block start x address
 */
#define ISP_AWB_X_START    0x00000FFFU
#define ISP_AWB_X_START_M  (ISP_AWB_X_START_V << ISP_AWB_X_START_S)
#define ISP_AWB_X_START_V  0x00000FFFU
#define ISP_AWB_X_START_S  12

/** ISP_AWB_BY_REG register
 *  awb window register in y-direction
 */
#define ISP_AWB_BY_REG (DR_REG_ISP_BASE + 0x268)
/** ISP_AWB_Y_BSIZE : R/W; bitpos: [11:0]; default: 0;
 *  Configures every block y size
 */
#define ISP_AWB_Y_BSIZE    0x00000FFFU
#define ISP_AWB_Y_BSIZE_M  (ISP_AWB_Y_BSIZE_V << ISP_AWB_Y_BSIZE_S)
#define ISP_AWB_Y_BSIZE_V  0x00000FFFU
#define ISP_AWB_Y_BSIZE_S  0
/** ISP_AWB_Y_START : R/W; bitpos: [23:12]; default: 0;
 *  Configures first block start y address
 */
#define ISP_AWB_Y_START    0x00000FFFU
#define ISP_AWB_Y_START_M  (ISP_AWB_Y_START_V << ISP_AWB_Y_START_S)
#define ISP_AWB_Y_START_V  0x00000FFFU
#define ISP_AWB_Y_START_S  12

/** ISP_STATE_REG register
 *  awb window register in y-direction
 */
#define ISP_STATE_REG (DR_REG_ISP_BASE + 0x26c)
/** ISP_TAIL_BUSY : RO; bitpos: [0]; default: 0;
 *  Represents isp_tail state
 */
#define ISP_TAIL_BUSY    (BIT(0))
#define ISP_TAIL_BUSY_M  (ISP_TAIL_BUSY_V << ISP_TAIL_BUSY_S)
#define ISP_TAIL_BUSY_V  0x00000001U
#define ISP_TAIL_BUSY_S  0
/** ISP_HEADER_BUSY : RO; bitpos: [1]; default: 0;
 *  Represents isp_header state
 */
#define ISP_HEADER_BUSY    (BIT(1))
#define ISP_HEADER_BUSY_M  (ISP_HEADER_BUSY_V << ISP_HEADER_BUSY_S)
#define ISP_HEADER_BUSY_V  0x00000001U
#define ISP_HEADER_BUSY_S  1

/** ISP_SHADOW_REG_CTRL_REG register
 *  shadow register ctrl register
 */
#define ISP_SHADOW_REG_CTRL_REG (DR_REG_ISP_BASE + 0x270)
/** ISP_BLC_UPDATE : R/W; bitpos: [0]; default: 0;
 *  Write 1 to update blc configuration register
 */
#define ISP_BLC_UPDATE    (BIT(0))
#define ISP_BLC_UPDATE_M  (ISP_BLC_UPDATE_V << ISP_BLC_UPDATE_S)
#define ISP_BLC_UPDATE_V  0x00000001U
#define ISP_BLC_UPDATE_S  0
/** ISP_DPC_UPDATE : R/W; bitpos: [1]; default: 0;
 *  Write 1 to update dpc configuration register
 */
#define ISP_DPC_UPDATE    (BIT(1))
#define ISP_DPC_UPDATE_M  (ISP_DPC_UPDATE_V << ISP_DPC_UPDATE_S)
#define ISP_DPC_UPDATE_V  0x00000001U
#define ISP_DPC_UPDATE_S  1
/** ISP_BF_UPDATE : R/W; bitpos: [2]; default: 0;
 *  Write 1 to update bf configuration register
 */
#define ISP_BF_UPDATE    (BIT(2))
#define ISP_BF_UPDATE_M  (ISP_BF_UPDATE_V << ISP_BF_UPDATE_S)
#define ISP_BF_UPDATE_V  0x00000001U
#define ISP_BF_UPDATE_S  2
/** ISP_WBG_UPDATE : R/W; bitpos: [3]; default: 0;
 *  Write 1 to update wbg configuration register
 */
#define ISP_WBG_UPDATE    (BIT(3))
#define ISP_WBG_UPDATE_M  (ISP_WBG_UPDATE_V << ISP_WBG_UPDATE_S)
#define ISP_WBG_UPDATE_V  0x00000001U
#define ISP_WBG_UPDATE_S  3
/** ISP_CCM_UPDATE : R/W; bitpos: [4]; default: 0;
 *  Write 1 to update ccm configuration register
 */
#define ISP_CCM_UPDATE    (BIT(4))
#define ISP_CCM_UPDATE_M  (ISP_CCM_UPDATE_V << ISP_CCM_UPDATE_S)
#define ISP_CCM_UPDATE_V  0x00000001U
#define ISP_CCM_UPDATE_S  4
/** ISP_SHARP_UPDATE : R/W; bitpos: [6]; default: 0;
 *  Write 1 to update sharp configuration register
 */
#define ISP_SHARP_UPDATE    (BIT(6))
#define ISP_SHARP_UPDATE_M  (ISP_SHARP_UPDATE_V << ISP_SHARP_UPDATE_S)
#define ISP_SHARP_UPDATE_V  0x00000001U
#define ISP_SHARP_UPDATE_S  6
/** ISP_COLOR_UPDATE : R/W; bitpos: [7]; default: 0;
 *  Write 1 to update color configuration register
 */
#define ISP_COLOR_UPDATE    (BIT(7))
#define ISP_COLOR_UPDATE_M  (ISP_COLOR_UPDATE_V << ISP_COLOR_UPDATE_S)
#define ISP_COLOR_UPDATE_V  0x00000001U
#define ISP_COLOR_UPDATE_S  7
/** ISP_SHADOW_UPDATE_SEL : R/W; bitpos: [31:30]; default: 1;
 *  Configures shadow register update type. 0: no shadow register. 1: update every
 *  vsyn. 2: update only the next vsync after write reg_xxx_update
 */
#define ISP_SHADOW_UPDATE_SEL    0x00000003U
#define ISP_SHADOW_UPDATE_SEL_M  (ISP_SHADOW_UPDATE_SEL_V << ISP_SHADOW_UPDATE_SEL_S)
#define ISP_SHADOW_UPDATE_SEL_V  0x00000003U
#define ISP_SHADOW_UPDATE_SEL_S  30

