#define PMS_LP_MM_FLASH_ALLOW_M  (PMS_LP_MM_FLASH_ALLOW_V << PMS_LP_MM_FLASH_ALLOW_S)
#define PMS_LP_MM_FLASH_ALLOW_V  0x00000001U
#define PMS_LP_MM_FLASH_ALLOW_S  1
