#define LP_REG_RSCK_I_EDGE_M  (LP_REG_RSCK_I_EDGE_V << LP_REG_RSCK_I_EDGE_S)
#define LP_REG_RSCK_I_EDGE_V  0x00000001U
#define LP_REG_RSCK_I_EDGE_S  8
