    volatile csi_brg_int_st_reg_t int_st;
    volatile csi_brg_int_ena_reg_t int_ena;
    volatile csi_brg_dma_req_interval_reg_t dma_req_interval;
    volatile csi_brg_dmablk_size_reg_t dmablk_size;
