#define SDHOST_IDINTEN_FBE_M  (SDHOST_IDINTEN_FBE_V << SDHOST_IDINTEN_FBE_S)
#define SDHOST_IDINTEN_FBE_V  0x00000001U
#define SDHOST_IDINTEN_FBE_S  2
