#define SDHOST_IDINTEN_CES_M  (SDHOST_IDINTEN_CES_V << SDHOST_IDINTEN_CES_S)
#define SDHOST_IDINTEN_CES_V  0x00000001U
#define SDHOST_IDINTEN_CES_S  5
