#define SDHOST_IDINTEN_NI    (BIT(8))
#define SDHOST_IDINTEN_NI_M  (SDHOST_IDINTEN_NI_V << SDHOST_IDINTEN_NI_S)
#define SDHOST_IDINTEN_NI_V  0x00000001U
#define SDHOST_IDINTEN_NI_S  8
