#define SDHOST_ENABLE_SHIFT_REG    0x0000000FU
#define SDHOST_ENABLE_SHIFT_REG_M  (SDHOST_ENABLE_SHIFT_REG_V << SDHOST_ENABLE_SHIFT_REG_S)
