#define SDHOST_CCLLKIN_EDGE_H    0x0000000FU
#define SDHOST_CCLLKIN_EDGE_H_M  (SDHOST_CCLLKIN_EDGE_H_V << SDHOST_CCLLKIN_EDGE_H_S)
