#define SPI1_MEM_S_USR_ADDR_VALUE    0xFFFFFFFFU
#define SPI1_MEM_S_USR_ADDR_VALUE_M  (SPI1_MEM_S_USR_ADDR_VALUE_V << SPI1_MEM_S_USR_ADDR_VALUE_S)
