#define SPI1_MEM_S_FREAD_DIO_M  (SPI1_MEM_S_FREAD_DIO_V << SPI1_MEM_S_FREAD_DIO_S)
#define SPI1_MEM_S_FREAD_DIO_V  0x00000001U
#define SPI1_MEM_S_FREAD_DIO_S  23
