#define SPI_MEM_S_AR_SIZE0_1_SUPPORT_EN    (BIT(21))
#define SPI_MEM_S_AR_SIZE0_1_SUPPORT_EN_M  (SPI_MEM_S_AR_SIZE0_1_SUPPORT_EN_V << SPI_MEM_S_AR_SIZE0_1_SUPPORT_EN_S)
#define SPI_MEM_S_AR_SIZE0_1_SUPPORT_EN_V  0x00000001U
#define SPI_MEM_S_AR_SIZE0_1_SUPPORT_EN_S  21
/** SPI_MEM_S_AW_SIZE0_1_SUPPORT_EN : R/W; bitpos: [22]; default: 1;
 *  1: MSPI supports AWSIZE 0~3. 0: When AWSIZE 0~1, MSPI reply SLV_ERR.
 */
#define SPI_MEM_S_AW_SIZE0_1_SUPPORT_EN    (BIT(22))
#define SPI_MEM_S_AW_SIZE0_1_SUPPORT_EN_M  (SPI_MEM_S_AW_SIZE0_1_SUPPORT_EN_V << SPI_MEM_S_AW_SIZE0_1_SUPPORT_EN_S)
#define SPI_MEM_S_AW_SIZE0_1_SUPPORT_EN_V  0x00000001U
#define SPI_MEM_S_AW_SIZE0_1_SUPPORT_EN_S  22
