#define SPI_MEM_S_RAM0_EN    (BIT(27))
#define SPI_MEM_S_RAM0_EN_M  (SPI_MEM_S_RAM0_EN_V << SPI_MEM_S_RAM0_EN_S)
#define SPI_MEM_S_RAM0_EN_V  0x00000001U
#define SPI_MEM_S_RAM0_EN_S  27
