#define SPI_MEM_S_CLK_EQU_SYSCLK_M  (SPI_MEM_S_CLK_EQU_SYSCLK_V << SPI_MEM_S_CLK_EQU_SYSCLK_S)
#define SPI_MEM_S_CLK_EQU_SYSCLK_V  0x00000001U
#define SPI_MEM_S_CLK_EQU_SYSCLK_S  31

